CREATE PROJECTION POLICY my_proj_policy
    AS () RETURNS PROJECTION_CONSTRAINT ->
    PROJECTION_CONSTRAINT(ALLOW => false);

CREATE OR REPLACE PROJECTION POLICY IF NOT EXISTS my_db.my_schema.my_proj_policy
    AS () RETURNS PROJECTION_CONSTRAINT ->
    CASE
        WHEN CURRENT_ROLE() IN ('ANALYST') THEN PROJECTION_CONSTRAINT(ALLOW => true)
        ELSE PROJECTION_CONSTRAINT(ALLOW => false)
    END
    COMMENT = 'Hide this column from SELECT';
